/**
 * Runtime source-presence gate from the frozen Core + SGD 122-identity census.
 * This is a source-review filter, never an installation/host/wallet permit.
 *
 * The ledger snapshot is generated by tools/build-droid-component-source-status.mjs.
 * No runtime fetch(), no second hand-authored PASS/HOLD list.
 */
import { DROID_SOURCE_REVIEW_ROWS } from '../../data/generated-droid-component-source-status.js';

const CANON_BY_ID = new Map(DROID_SOURCE_REVIEW_ROWS.map(([id, name, decision]) =>
  [id, Object.freeze({ canonicalId: id, canonicalName: name, sourceDecision: decision })]));
const identityKey = value => String(value ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
const CANON_BY_NAME = new Map(
  [...CANON_BY_ID.values()].map(row => [identityKey(row.canonicalName), row])
);

// Explicitly adjudicated *identity* aliases only. An alias does not certify
// the old catalog's pricing, mass, variant or application behavior.
const ID_ALIASES = Object.freeze({
  remote: 'droid-remote-processor',
  'sr5-shield-generator': 'droid-shield-generator-sr-5',
  'sr10-shield-generator': 'droid-shield-generator-sr-10',
  'sr15-shield-generator': 'droid-shield-generator-sr-15',
  'sr20-shield-generator': 'droid-shield-generator-sr-20',
  'communications-countermeasures': 'droid-communications-countermeasure-system',
  'weapon-detector-package': 'droid-weapon-detector',
  'projectile-appendage': 'droid-projectile-hand'
});

// The Core translator has FOUR source tiers, not these three older catalog
// objects. Retaining their names as identities must not imply that their old
// displayed prices are valid. Same for other unmodeled multi-tier aliases.
const NEEDS_VARIANT_RECONCILIATION = Object.freeze({
  'basic-translator': 'droid-translator-unit',
  'advanced-translator': 'droid-translator-unit',
  'universal-translator': 'droid-translator-unit',
  'laminanium-heavy-plating': 'droid-laminanium-plating'
});
const LOCOMOTION_PRICE_HOLDS = new Set([
  'droid-walking', 'droid-wheeled', 'droid-tracked',
  'droid-hovering', 'droid-flying'
]);

export function resolveDroidComponentSourceReview(definition, {
  operationPhase = null,
  locomotionSlotOrdinal = null,
  restrictedLocomotion = null
} = {}) {
  const id = typeof definition === 'string'
    ? definition : (definition?.canonicalId ?? definition?.id ?? null);
  const name = typeof definition === 'string' ? definition : definition?.name;
  const literalId = String(id ?? '').trim().toLowerCase();
  const aliasedId = ID_ALIASES[literalId] ?? literalId;
  const variantAliasId = NEEDS_VARIANT_RECONCILIATION[literalId] ?? null;
  const candidate = CANON_BY_ID.get(aliasedId)
    ?? CANON_BY_ID.get('droid-' + aliasedId)
    ?? CANON_BY_NAME.get(identityKey(name))
    ?? null;

  if (variantAliasId) {
    return {
      decision: 'BLOCKED', canonicalId: variantAliasId,
      sourceDecision: 'PASS',
      blockingReason: 'Catalog alias does not match the certified published variants; select a canonical source tier'
    };
  }
  if (!candidate) {
    return {
      decision: 'BLOCKED', canonicalId: null,
      sourceDecision: 'UNRECONCILED',
      blockingReason: 'Component is not reconciled to a certified Core/SGD source identity'
    };
  }
  if (candidate.sourceDecision === 'PASS') {
    return {
      decision: 'SOURCE_REVIEW_PASS', canonicalId: candidate.canonicalId,
      sourceDecision: 'PASS', blockingReason: null
    };
  }
  // Five locomotive price composition HOLDs have an explicitly printed,
  // non-restricted first-system arithmetic subset. Never allow it without
  // an explicit initial-build/first-slot/unrestricted context.
  if (LOCOMOTION_PRICE_HOLDS.has(candidate.canonicalId)
      && operationPhase === 'INITIAL_BUILD'
      && locomotionSlotOrdinal === 1
      && restrictedLocomotion === false) {
    return {
      decision: 'SOURCE_SAFE_SUBSET', canonicalId: candidate.canonicalId,
      sourceDecision: 'HOLD', blockingReason: null
    };
  }
  return {
    decision: 'BLOCKED', canonicalId: candidate.canonicalId,
    sourceDecision: candidate.sourceDecision,
    blockingReason: 'Published component mechanics are on source HOLD outside an explicitly certified subset'
  };
}
